 -- Solo coincidencias de nombre completo exacto (acentos/mayúsculas/espacios), sin similitud.
 -- Tamaños de pizza se expresan como el catálogo de Dodo IS. No vincula Thin ni combos por piezas.
 if not previa then
  for r in select * from public.menu_rappi_productos where version_id=v loop
   busqueda:=r.nombre||case lower(trim(r.tamano)) when '25 cm' then ' Pequeño' when '30 cm' then ' Mediano' when '35 cm' then ' Grande' when 'n/a' then '' else ' '||r.tamano end;
   select count(*),min(dodo_id) into cantidad,candidato from public.productos_venta where
    regexp_replace(translate(lower(trim(nombre)),'áéíóúüñ','aeiouun'),'\s+',' ','g')=regexp_replace(translate(lower(trim(busqueda)),'áéíóúüñ','aeiouun'),'\s+',' ','g');
   if cantidad=1 and not exists(select 1 from public.menu_rappi_productos where version_id=v and dodo_id=candidato) then perform public.vincular_menu_rappi(r.id,r.revision,candidato);end if;
  end loop;
 end if;
 raise notice 'CARGA OK: versión % · 56 precios Rappi · costos vigentes conservados',v;
end $carga$;
commit;
select 'CARGA OK' as resultado,v.vigente_desde,count(*) as productos,count(*) filter(where p.dodo_id is null) as pendientes_de_vincular from public.menu_rappi_versiones v join public.menu_rappi_productos p on p.version_id=v.id where v.vigente_desde='2026-10-01' and v.huella='c8be2630d4418019ae94145ccf793c7f2942c2360d25499394e6d662fd98f9da' group by v.vigente_desde;
